esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will try to call create with arbitrary encodedParameters and ownedBy
    // The rule: if create succeeds (does not revert) it returns an address that must be a contract
    // (i.e., address.code.length > 0 as observable), and c.roundImplementation equals the implementation
    // that was used for clone (observable via public getter), and the returned address is non-zero.
    // Because events are not directly readable here, we instead assert that when create succeeds,
    // the returned address is non-zero and has code; if it reverts, that's allowed.

    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        // Preconditions: no precondition on encodedParameters; caller (this contract) may or may not be a program operator.
        // We will record pre-state of roundImplementation and alloSettings to use in the invariant.
        address beforeRoundImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address beforeAllo = c.alloSettings(); if (__ESBMC_reverted()) return;

        bool reverted;
        address created;
        // Call create and capture whether it reverts
        address addr = c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            created = address(0);
        } else {
            reverted = false;
            created = addr;
        }

        // After the call, either it reverted (no state change expected) OR it returned a contract address.
        // We cannot rely on events, but we can observe public getters and the returned address's code size.
        // Assert the general rule:
        // If create did not revert then:
        //  - created != address(0)
        //  - created.code.length > 0 (is a contract)
        //  - c.roundImplementation() equals beforeRoundImpl (creating a clone should not change the stored implementation)
        //  - c.alloSettings() equals beforeAllo (create should not change alloSettings)
        assert(
            reverted
            || (
                created != address(0)
                && address(created).code.length > 0
                && c.roundImplementation() == beforeRoundImpl
                && c.alloSettings() == beforeAllo
            )
        );
    }

    receive() external payable {}
}

